typedef struct z_t5697_t {
    uint64_t capacity;
    uint64_t length;
    uint64_t entries_len;
    uint64_t entries_cap;
    int64_t* indices;
    z_t5697_entry_t* entries;
} z_t5697_t;

static uint64_t z_t5697_hash_key(const z_t64_t* _key);
