static z_t656_t z_t5697_getMut(z_t5697_t* _this, const z_t64_t* _key) {
    z_t656_t _r = {0};
    uint64_t h = z_t5697_hash_key(_key);
    int64_t idx = z_t5697_find(_this, _key, h, NULL);
    if (idx >= 0) {
        _r.tag = Z_T656_TAG_1;
        _r.data = &_this->entries[idx].value;
    } else {
        _r.tag = Z_T656_TAG_0;
        _r.data = NULL;
    }
    return _r;
}

